function showHeroProgressionIntro(done){
  state.heroProgressionSeen=true;save();
  showHeroGuide(0,done);
}
function showHeroGuide(step=0,done=null){
  const lvl=heroLevel('aldric'),xp=heroProgress('aldric'),rank=heroSkillRank('aldric');
  const scenes=[
    {title:'Aldric también progresa',icon:'♞',copy:`<strong>Nivel ${lvl} · ${xp}/100 XP</strong><p>Los combates dan <b>experiencia al héroe</b>. Al llenar la barra, Aldric sube de nivel y mejora sus estadísticas.</p>`,button:'Ver cómo mejora'},
    {title:'Nivel y habilidad no son lo mismo',icon:'✦',copy:`<strong>Baluarte de Valoria · Rango ${rank}/5</strong><p>Subir de nivel desbloquea crecimiento. Las <b>habilidades se mejoran aparte</b> gastando Esencia Heroica, así puedes decidir en qué héroe invertir.</p>`,button:'Ver especialización'},
    {title:'Las Resonancias cambian su función',icon:'◇',copy:`<p>Una <b>Resonancia de la Brecha</b> modifica estadísticas y especialización. No es equipo genérico: sirve para construir una versión distinta del mismo héroe.</p><div class="chapter-reward-preview"><b>ALDRIC · TU PRIMER HÉROE</b><small>XP → nivel · Esencia → habilidad · Resonancia → especialización</small></div>`,button:'Abrir Salón de Héroes'}
  ];
  const s=scenes[Math.min(step,2)];
  openModal('Tutorial de héroes',`<div class="hero-tutorial hero-progression-intro"><b>CAPÍTULO II · HÉROES</b><span style="font-size:38px;display:block;margin:10px 0">${s.icon}</span><h3>${s.title}</h3>${s.copy}</div><button id="hero-guide-next" class="primary">${s.button}</button>`);
  modal.querySelector('.close')?.remove();
  $('#hero-guide-next').onclick=()=>{closeModal();if(step<2)return showHeroGuide(step+1,done);heroesModal();if(done)setTimeout(done,500);};
}

